  INSERT INTO public.assessment_items (id, assessment_id, competency_id, type, prompt, points, order_index, difficulty_level)
  VALUES
  ('a0000000-0000-0002-0000-000000000001', 'a0000000-0000-0000-0000-000000000002', '8f79f1ec-d4f0-4b68-b948-0deade1d3969', 'MCQ', 'Khi cần tìm tài liệu học thuật đáng tin cậy, công cụ nào phù hợp nhất?', 1, 1, 'FOUNDATION'),
