  ('a0000000-0000-0002-0000-000000000003', 'a0000000-0000-0000-0000-000000000002', 'bb7785b0-0a0f-478d-9b40-a32388195cf2', 'MCQ', 'Khi tìm tài liệu về “năng lực số sinh viên”, cách tìm nào hiệu quả hơn?', 1, 3, 'ADVANCED'),
  ('a0000000-0000-0002-0000-000000000004', 'a0000000-0000-0000-0000-000000000002', '8f79f1ec-d4f0-4b68-b948-0deade1d3969', 'MCQ', 'Dấu ngoặc kép trong tìm kiếm Google dùng để làm gì?', 1, 4, 'INTERMEDIATE'),
  ('a0000000-0000-0002-0000-000000000005', 'a0000000-0000-0000-0000-000000000002', '6c475f25-7c43-4a43-888f-450c0d103d44', 'MCQ', 'Khi muốn loại bỏ một từ khỏi kết quả tìm kiếm, có thể dùng ký hiệu nào?', 1, 5, 'FOUNDATION'),
  ('a0000000-0000-0002-0000-000000000006', 'a0000000-0000-0000-0000-000000000002', 'bb7785b0-0a0f-478d-9b40-a32388195cf2', 'MCQ', 'Khi tìm văn bản pháp luật chính thức, nên ưu tiên nguồn nào?', 1, 6, 'ADVANCED'),
  ('a0000000-0000-0002-0000-000000000007', 'a0000000-0000-0000-0000-000000000002', '8f79f1ec-d4f0-4b68-b948-0deade1d3969', 'MCQ', 'Khi tìm thông tin mới, yếu tố nào cần kiểm tra?', 1, 7, 'FOUNDATION'),
