  ('a0000000-0000-0002-0000-000000000009', 'a0000000-0000-0000-0000-000000000002', 'bb7785b0-0a0f-478d-9b40-a32388195cf2', 'MCQ', 'Khi tìm kiếm bằng AI, người dùng nên làm gì?', 1, 9, 'ADVANCED'),
