  ('a0000000-0000-0002-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', '8f79f1ec-d4f0-4b68-b948-0deade1d3969', 'MCQ', 'Khi tải tài liệu từ Internet, cần chú ý điều gì trước tiên?', 1, 13, 'FOUNDATION'),
  ('a0000000-0000-0002-0000-000000000014', 'a0000000-0000-0000-0000-000000000002', '6c475f25-7c43-4a43-888f-450c0d103d44', 'MCQ', 'Định dạng PDF thường phù hợp để làm gì?', 1, 14, 'INTERMEDIATE'),
  ('a0000000-0000-0002-0000-000000000015', 'a0000000-0000-0000-0000-000000000002', 'bb7785b0-0a0f-478d-9b40-a32388195cf2', 'MCQ', 'Khi tìm hình ảnh sử dụng trong bài thuyết trình, cần chú ý điều gì?', 1, 15, 'ADVANCED'),
